contracts/interface/SecondSwap_Vesting.s.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/** 
 * @title SecondSwap Vesting Interface
 * @notice Defines core functionality for token vesting operations
 * @dev Interface for implementing token vesting with transfer and claiming capabilities
 */
interface SecondSwap_Vesting {
    /** 
     * @notice Gets the total amount of tokens allocated to a beneficiary
     * @dev Returns full allocation regardless of claimed amount
     * @param _beneficiary Address of the vesting beneficiary
     * @return Total amount of tokens allocated
     */
    function total(address _beneficiary) external view returns (uint256);

    /** 
     * @notice Gets the amount of tokens still available to a beneficiary
     * @dev Returns total allocation minus claimed amount
     * @param _beneficiary Address of the vesting beneficiary
     * @return Amount of tokens still available to claim
     */
    function available(address _beneficiary) external view returns (uint256);

    /** 
     * @notice Calculates the amount of tokens currently claimable by a beneficiary
     * @dev Returns both claimable amount and number of steps claimable
     * @param _beneficiary Address of the vesting beneficiary
     * @return Amount of tokens currently claimable
     * @return Number of vesting steps that can be claimed
     */
    function claimable(address _beneficiary) external view returns (uint256, uint256);

    /** 
     * @notice Claims available tokens for the caller
     * @dev Transfers claimable tokens to msg.sender
     */
    function claim() external;

    /** 
     * @notice Transfers vested tokens between addresses
     * @dev Allows transfer of vesting allocation between users
     * @param grantor Address transferring the vesting
     * @param beneficiary Address receiving the vesting
     * @param _amount Amount of tokens to transfer
     */
    function transferVesting(
        address grantor,
        address beneficiary,
        uint256 _amount
    ) external;

    /** 
     * @notice Creates a new vesting schedule for a beneficiary
     * @dev Sets up vesting allocation for a single address
     * @param beneficiary Address to receive the vesting
     * @param totalAmount Total amount of tokens to vest
     */
    function createVesting(
        address beneficiary,
        uint256 totalAmount
    ) external;

    /** 
     * @notice Creates multiple vesting schedules in batch
     * @dev Sets up vesting allocations for multiple addresses
     * @param beneficiaries Array of addresses to receive vesting
     * @param totalAmounts Array of token amounts corresponding to each beneficiary
     */
    function createVestings(
        address[] memory beneficiaries,
        uint256[] memory totalAmounts
    ) external;
}

contracts/SecondSwap_Marketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "./interface/IERC20.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol"; //  3.6. DOS caused by the use of transfer and transferFrom functions
import "./interface/SecondSwap_IMarketplaceSetting.sol";
import "./interface/SecondSwap_IWhitelist.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "./SecondSwap_WhitelistDeployer.sol";
import "hardhat/console.sol";
/** 
* @title SecondSwap Marketplace Contract
* @notice Handles the listing and trading of vested tokens
* @dev This contract is upgradeable and manages the marketplace functionality for SecondSwap
*/
contract SecondSwap_Marketplace is Initializable {
    using SafeERC20 for IERC20; //  3.6. DOS caused by the use of transfer and transferFrom functions

    /**
     * @notice Enumeration of possible listing statuses
     * @dev Used to track the current state of a listing
     * @param LIST Active listing that can be purchased
     * @param SOLDOUT Listing where all tokens have been sold
     * @param DELIST Listing that has been cancelled by the seller
     */
    enum Status { LIST, SOLDOUT, DELIST }
    /**
     * @notice Enumeration of listing types
     * @dev Determines how tokens can be purchased from the listing
     * @param PARTIAL Allows partial purchases of the listed amount
     * @param SINGLE Requires the entire listed amount to be purchased at once
     */
    enum ListingType { PARTIAL, SINGLE }
    /** 
    * @notice Enumeration of discount types
    * @dev Defines how price discounts are calculated
    * @param NO No discount applied
    * @param LINEAR Discount increases linearly with purchase amount
    * @param FIX Fixed percentage discount regardless of amount
    */
    enum DiscountType { NO, LINEAR, FIX }
    /** 
    * @notice Structure containing all listing information
    * @dev Used to store and manage listing details
    * @param seller Address of the token seller
    * @param total Total amount of tokens initially listed
    * @param balance Current remaining amount of tokens
    * @param pricePerUnit Price per token unit
    * @param listingType Type of listing (PARTIAL or SINGLE)
    * @param discountType Type of discount applied
    * @param discountPct Discount percentage (0-10000)
    * @param listTime Timestamp when listing was created
    * @param whitelist Address of whitelist contract if private listing
    * @param minPurchaseAmt Minimum amount that can be purchased
    * @param status Current status of the listing
    * @param currency Address of token used for payment
    */
    struct Listing {
        address seller;
        uint256 total;
        uint256 balance;
        uint256 pricePerUnit;
        ListingType listingType;
        DiscountType discountType;
        uint256 discountPct;
        uint256 listTime;
        address whitelist;
        uint256 minPurchaseAmt;
        Status status;
        address currency;
    }
    /**
    * @notice Address of the marketplace settings contract
    * @dev Used to access marketplace configuration and parameters
    */
    address public marketplaceSetting;
    
    /**
    * @notice Mapping of vesting plan addresses to their listing IDs and details
    * @dev First key is vesting plan address, second key is listing ID
    */
    mapping(address => mapping(uint256 => Listing)) public listings;

    /**
    * @notice Mapping of vesting plan addresses to their next available listing ID
    * @dev Used to generate unique listing IDs for each vesting plan
    */
    mapping(address => uint256) public nextListingId;

    /**
    * @notice Mapping of token addresses to their support status
    * @dev Tracks which tokens are accepted as payment currency
    */
    mapping(address => bool) public isTokenSupport;

    /**
    * @notice Base unit for percentage calculations
    * @dev 10000 represents 100%, used for fee and discount calculations
    */
    uint256 public constant BASE = 10000;

    /**
    * @notice Emitted when a new listing is created
    * @param vestingPlan Address of the vesting plan contract
    * @param listingId Unique identifier of the listing
    */
    event Listed(address indexed vestingPlan, uint256 indexed listingId);

    /**
    * @notice Emitted when a listing is delisted
    * @param vestingPlan Address of the vesting plan contract
    * @param listingId Unique identifier of the listing
    * @param penaltyFee Amount of penalty fee charged for early delisting
    * @param seller Address of the seller who delisted
    */
    event Delisted(address indexed vestingPlan, uint256 indexed listingId, uint256 penaltyFee, address seller);

    /**
    * @notice Emitted when a purchase is completed
    * @param vestingPlan Address of the vesting plan contract
    * @param listingId Unique identifier of the listing
    * @param buyer Address of the buyer
    * @param amount Amount of tokens purchased
    * @param referral Address of the referrer
    * @param buyerFee Amount of fees paid by buyer
    * @param sellerFee Amount of fees paid by seller
    * @param referralReward Amount of reward paid to referrer
    */
    event Purchased(
        address indexed vestingPlan,
        uint256 indexed listingId,
        address buyer,
        uint256 amount,
        address referral,
        uint256 buyerFee,
        uint256 sellerFee,
        uint256 referralReward
    );

    /**
    * @notice Emitted when a whitelist is created for a private listing
    * @param vestingPlan Address of the vesting plan contract
    * @param listingId Unique identifier of the listing
    * @param whitelistAddress Address of the deployed whitelist contract
    * @param seller Address of the seller
    * @param maxWhitelist Maximum number of addresses that can be whitelisted
    */
    event WhitelistCreated(
        address indexed vestingPlan,
        uint256 indexed listingId,
        address whitelistAddress,
        address seller,
        uint256 maxWhitelist
    );

    /**
    * @notice Emitted when a new token is added
    * @param token address ot the new token
    */
    event CoinAdded(address indexed token);

    /**
    * @notice Initializes the marketplace contract
    * @dev Implementation of initializer for upgradeable contract pattern
    * @param _token Initial supported token address for payments
    * @param _marketplaceSetting Address of the marketplace settings contract
    */
    function initialize(
        address _token,
        address _marketplaceSetting
    ) public initializer {
        isTokenSupport[_token] = true;
        marketplaceSetting = _marketplaceSetting;
    }

    /** 
    * @notice Modifier to prevent actions when marketplace is frozen
    * @dev Checks marketplace freeze status through settings contract
    * @custom:throws SS_Marketplace: Marketplace is currently frozen
    */
    modifier isFreeze() {
        require(!IMarketplaceSetting(marketplaceSetting).isMarketplaceFreeze(), 
            "SS_Marketplace: Marketplace is currently frozen");
        _;
    }

    /** 
    * @notice Adds a new token as supported payment currency
    * @dev Only callable by marketplace admin
    * @param _token Address of the token to add as supported currency
    * @custom:throws SS_Marketplace: Unauthorized user - If caller is not admin
    * @custom:throws SS_Marketplace: Token is currently supported - If token already supported
    */
    function addCoin(address _token) external {
        require(msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(), 
            "SS_Marketplace: Unauthorized user");
        require(!isTokenSupport[_token],
            "SS_Marketplace: Token is currently supported");
        // try IERC20Extended(_token).decimals() returns (uint8 decimals) {
        //     require(decimals <= 18, "SS_Marketplace: Token decimals too high");
        //     require(decimals > 0, "SS_Marketplace: Token decimals must be greater than 0");
            
        //     isTokenSupport[_token] = true;
        //     emit CoinAdded(_token); // Emit event when coin is added
        // } catch {
        //     revert("SS_Marketplace: Token must implement decimals function");
        // }
        isTokenSupport[_token] = true;
    }

    /** 
    * @notice Creates a new listing for vested tokens
    * @dev Transfers tokens to marketplace and creates listing record
    * @param _vestingPlan Address of the vesting plan contract
    * @param _amount Total amount of tokens to list
    * @param _price Price per token unit
    * @param _discountPct Discount percentage (0-10000)
    * @param _listingType PARTIAL allows partial fills, SINGLE requires complete fill
    * @param _discountType NO = no discount, LINEAR = progressive, FIX = fixed percentage
    * @param _maxWhitelist Maximum number of addresses for whitelist (if private)
    * @param _currency Address of token used for payment
    * @param _minPurchaseAmt Minimum purchase amount allowed
    * @param _isPrivate If true, creates whitelist for private sale
    * @custom:throws SS_Marketplace: Minimum Purchase Amount cannot be more than listing amount
    * @custom:throws SS_Marketplace: Price must be greater than 0
    * @custom:throws SS_Marketplace: Invalid discount amount
    * @custom:throws SS_Marketplace: Invalid listing amount
    * @custom:throws SS_Marketplace: Payment token is not supported
    * @custom:throws SS_Marketplace: Minimum whitelist user cannot be 0
    */
    function listVesting(
        address _vestingPlan,
        uint256 _amount,
        uint256 _price,
        uint256 _discountPct,
        ListingType _listingType,
        DiscountType _discountType,
        uint256 _maxWhitelist,
        address _currency,
        uint256 _minPurchaseAmt,
        bool _isPrivate
    ) external isFreeze {
        require(_listingType != ListingType.SINGLE || (_minPurchaseAmt > 0 && _minPurchaseAmt <= _amount),
            "SS_Marketplace: Minimum Purchase Amount cannot be more than listing amount");
        require(_price > 0, "SS_Marketplace: Price must be greater than 0");
        require((_discountType != DiscountType.NO && _discountPct > 0) || (_discountType == DiscountType.NO),
            "SS_Marketplace: Invalid discount amount");
        require(_amount > 0 ,"SS_Marketplace: Invalid listing amount"); // 3.10. Inefficient _listingType check
        require(isTokenSupport[_currency], "SS_Marketplace: Payment token is not supported");

        // // uint256 baseAmount = (_amount * _price) /uint256(10 ** (IERC20Extended(_currency).decimals())); // 3.1. Rounding issue leads to total drain of vesting entries
        // uint256 baseAmount = (_amount * _price) /1 ether; // 3.1. Rounding issue leads to total drain of vesting entries
        // require(baseAmount > 0,"SS_Marketplace: Cannot list amount it is too little");  // 3.1. Rounding issue leads to total drain of vesting entries


        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager())
            .listVesting(msg.sender, _vestingPlan, _amount);
        
        uint256 listingId = nextListingId[_vestingPlan]++;
        address whitelistAddress;

        if (_isPrivate) {
            require(_maxWhitelist > 0, "SS_Marketplace: Minimum whitelist user cannot be 0");
            whitelistAddress = SecondSwap_WhitelistDeployer(IMarketplaceSetting(marketplaceSetting).whitelistDeployer())
                .deployWhitelist(_maxWhitelist, msg.sender);
            emit WhitelistCreated(_vestingPlan, listingId, whitelistAddress, msg.sender, _maxWhitelist);
        }

        listings[_vestingPlan][listingId] = Listing({
            seller: msg.sender,
            total: _amount,
            balance: _amount,
            pricePerUnit: _price,
            listingType: _listingType,
            discountType: _discountType,
            discountPct: _discountPct,
            listTime: block.timestamp,
            whitelist: whitelistAddress,
            currency: _currency,
            minPurchaseAmt: _minPurchaseAmt,
            status: Status.LIST
        });
        emit Listed(_vestingPlan, listingId);
    }

    /** 
    * @notice Removes a listing from the marketplace
    * @dev Handles early unlisting penalties and token returns
    * @param _vestingPlan Address of the vesting plan contract
    * @param _listingId ID of the listing to remove
    * @custom:throws SS_Marketplace: Listing not active
    * @custom:throws SS_Marketplace: Not the seller
    * @custom:throws SS_Marketplace: Penalty fee required for early unlisting
    */
    function unlistVesting(
        address _vestingPlan,
        uint256 _listingId
    ) external isFreeze {
        Listing storage listing = listings[_vestingPlan][_listingId];
        require(listing.status == Status.LIST, "SS_Marketplace: Listing not active");
        require(listing.seller == msg.sender || msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(),
            "SS_Marketplace: Not the seller");
        uint256 _penaltyFee = 0;
        if (msg.sender != IMarketplaceSetting(marketplaceSetting).s2Admin()){ //  3.4. The s2Admin is unable to unlist vesting
            if ((listing.listTime + IMarketplaceSetting(marketplaceSetting).minListingDuration()) > block.timestamp) {
                require( (IMarketplaceSetting(marketplaceSetting).usdt()).balanceOf(msg.sender) >= IMarketplaceSetting(marketplaceSetting).penaltyFee(),"SS_Marketplace: Penalty fee required for early unlisting"); // 3.7. Value difference caused by the same penalty fee
                (IMarketplaceSetting(marketplaceSetting).usdt()).safeTransferFrom(msg.sender, IMarketplaceSetting(marketplaceSetting).feeCollector(), // 3.7. Value difference caused by the same penalty fee
                    IMarketplaceSetting(marketplaceSetting).penaltyFee()); //  3.6. DOS caused by the use of transfer and transferFrom functions
                _penaltyFee = IMarketplaceSetting(marketplaceSetting).penaltyFee();
            }
        }
        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager()).unlistVesting(listing.seller, _vestingPlan, listing.balance); //  3.4. The s2Admin is unable to unlist vesting

        listing.status = Status.DELIST; // 3.3. Buyer can choose listing price
        listing.balance = 0; // 3.3. Buyer can choose listing price

        emit Delisted(_vestingPlan, _listingId, _penaltyFee, msg.sender);
    }

    /**
    * @notice Validates a purchase attempt
    * @dev Checks various conditions that must be met for a valid purchase
    * @param listing The listing to validate against
    * @param _amount Amount of tokens to purchase
    * @param _referral Address of the referrer
    * @custom:throws SS_Marketplace: Invalid referral
    * @custom:throws SS_Marketplace: Not whitelisted
    * @custom:throws SS_Marketplace: Invalid Purchase amount
    * @custom:throws SS_Marketplace: Invalid amount
    * @custom:throws SS_Marketplace: Insufficient
    */
    function _validatePurchase(
        Listing storage listing,
        uint256 _amount,
        address _referral
    ) private view {
        require(listing.status == Status.LIST, "SS_Marketplace: Listing not active"); // 3.3. Buyer can choose listing price
        require(msg.sender != _referral, "SS_Marketplace: Invalid referral");
        require(listing.whitelist == address(0) || IWhitelist(listing.whitelist).validateAddress(msg.sender),
            "SS_Marketplace: Not whitelisted");
        require(listing.listingType == ListingType.SINGLE || (_amount >= listing.minPurchaseAmt || _amount == listing.balance),
            "SS_Marketplace: Invalid Purchase amount");
        require(listing.listingType != ListingType.SINGLE || _amount == listing.total,
            "SS_Marketplace: Invalid amount");
        require(_amount <= listing.balance, "SS_Marketplace: Insufficient");
    }

    /**
     * @notice Calculates the final price per token including discounts
     * @dev Applies linear or fixed discounts based on listing configuration
     * @param listing The listing to calculate price for
     * @param _amount Amount of tokens being purchased
     * @return Final price per token after discounts
     */
    function _getDiscountedPrice(
        Listing storage listing,
        uint256 _amount
    ) private view returns (uint256) {
        uint256 discountedPrice = listing.pricePerUnit;
        
        if (listing.discountType == DiscountType.LINEAR) {
            discountedPrice = discountedPrice *
                (BASE - (_amount * listing.discountPct / listing.total)) / BASE;
        } else if (listing.discountType == DiscountType.FIX) {
            discountedPrice = discountedPrice *
                (BASE - listing.discountPct) / BASE;
        }
        return discountedPrice;
    }

    /**
     * 
     * @notice Retrieves buyer and seller fee rates for a vesting plan
     * @dev Checks for plan-specific fees, falls back to global fees if not set
     * @param _vestingPlan Address of the vesting plan
     * @return bfee Buyer fee percentage
     * @return sfee Seller fee percentage
     */
    function _getFees(
        address _vestingPlan
    ) private view returns (uint256 bfee, uint256 sfee) {
        (int256 vpbf, int256 vpsf) = IMarketplaceSetting(marketplaceSetting).getVestingFees(_vestingPlan);
        bfee = vpbf > -1 ? uint256(vpbf) : IMarketplaceSetting(marketplaceSetting).buyerFee();
        sfee = vpsf > -1 ? uint256(vpsf) : IMarketplaceSetting(marketplaceSetting).sellerFee();
    }

    /** 
     * @notice Handles all token transfers during a purchase
     * @dev Transfers payment tokens between buyer, seller, referrer, and fee collector
     * @param listing The listing being purchased from
     * @param _amount Amount of tokens being purchased
     * @param discountedPrice Price per token after discounts
     * @param bfee Buyer fee percentage
     * @param sfee Seller fee percentage
     * @param _referral Address of the referrer
     * @return buyerFeeTotal Total fees paid by buyer
     * @return sellerFeeTotal Total fees paid by seller
     * @return referralFeeCost Amount paid to referrer 
     */
    function _handleTransfers(
        Listing storage listing,
        uint256 _amount,
        uint256 discountedPrice,
        uint256 bfee,
        uint256 sfee,
        address _referral
    ) private returns (uint256 buyerFeeTotal, uint256 sellerFeeTotal, uint256 referralFeeCost) {
        // uint256 baseAmount = (_amount * discountedPrice) /uint256(10 ** (IERC20Extended(listing.currency).decimals())); // 3.1. Rounding issue leads to total drain of vesting entries

        uint256 baseAmount = (_amount * discountedPrice) /1 ether; // 3.1. Rounding issue leads to total drain of vesting entries
        //  console.log("baseAmount: ",baseAmount);
        // require(baseAmount > 0,"SS_Marketplace: Amount too little"); // 3.1. Rounding issue leads to total drain of vesting entries

        buyerFeeTotal = (baseAmount * bfee) / BASE;
        sellerFeeTotal = (baseAmount * sfee) / BASE;  

        IERC20(listing.currency).safeTransferFrom(msg.sender, address(this), (baseAmount + buyerFeeTotal)); //  3.6. DOS caused by the use of transfer and transferFrom functions
        
        referralFeeCost = 0;
        if (_referral != address(0) && listing.whitelist == address(0)) {
            referralFeeCost = buyerFeeTotal -(baseAmount * bfee * IMarketplaceSetting(marketplaceSetting).referralFee()) / (BASE * BASE);
            IERC20(listing.currency).safeTransfer(_referral, referralFeeCost); //  3.6. DOS caused by the use of transfer and transferFrom functions
        }

        IERC20(listing.currency).safeTransfer(listing.seller, (baseAmount - sellerFeeTotal)); //  3.6. DOS caused by the use of transfer and transferFrom functions
        
        uint256 feeCollectorTotal = (buyerFeeTotal - referralFeeCost + sellerFeeTotal);
        IERC20(listing.currency).safeTransfer(IMarketplaceSetting(marketplaceSetting).feeCollector(), feeCollectorTotal); //  3.6. DOS caused by the use of transfer and transferFrom functions
    }

    /**
     * @notice Executes a purchase of listed tokens
     * @dev Handles the complete purchase flow including validation, pricing, and transfers
     * @param _vestingPlan Address of the vesting plan contract
     * @param _listingId ID of the listing to purchase from
     * @param _amount Amount of tokens to purchase
     * @param _referral Address of the referrer (if any)
     * @custom:throws Various errors from _validatePurchase
     * @custom:emits Purchased
     */
    function spotPurchase(
        address _vestingPlan,
        uint256 _listingId,
        uint256 _amount,
        address _referral
    ) external isFreeze {
        // Get listing and validate purchase parameters
        Listing storage listing = listings[_vestingPlan][_listingId];
        _validatePurchase(listing, _amount, _referral);

        // Calculate fees and final price
        (uint256 bfee, uint256 sfee) = _getFees(_vestingPlan);
        uint256 discountedPrice = _getDiscountedPrice(listing, _amount);
        
        // Process all transfers
        (uint256 buyerFeeTotal, uint256 sellerFeeTotal, uint256 referralFeeCost) = 
            _handleTransfers(listing, _amount, discountedPrice, bfee, sfee, _referral);

        // Update listing status
        listing.balance -= _amount;
        listing.status = listing.balance == 0 ? Status.SOLDOUT : Status.LIST;

        // Complete the purchase through vesting manager
        IVestingManager(IMarketplaceSetting(marketplaceSetting).vestingManager())
            .completePurchase(msg.sender, _vestingPlan, _amount);

        // Emit purchase event
        emit Purchased(
            _vestingPlan,
            _listingId,
            msg.sender,
            _amount,
            _referral,
            buyerFeeTotal,
            sellerFeeTotal,
            referralFeeCost
        );
    }

    /**
     * @notice Updates the marketplace settings contract address
     * @dev Only callable by marketplace admin
     * @param _marketplaceSetting New address of the marketplace settings contract
     * @custom:throws SS_Marketplace: Unauthorized user
     * @custom:throws SS_Marketplace: Address cannot be null 
     */
    function setMarketplaceSettingAddress(address _marketplaceSetting) external {
        require(msg.sender == IMarketplaceSetting(marketplaceSetting).s2Admin(), 
            "SS_Marketplace: Unauthorized user");
        require(_marketplaceSetting != address(0),
            "SS_Marketplace: Address cannot be null");
        marketplaceSetting = _marketplaceSetting;
    }

    /**
     * @notice Returns the current version of the marketplace contract
     * @dev Used for version tracking in upgradeable contract pattern
     * @return String representing the contract version 
     */
    function version() public pure returns (string memory) {
        return "1.0.0";
    }
}

contracts/SecondSwap_MarketplaceSetting..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interface/SecondSwap_IMarketplaceSetting.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title SecondSwap Marketplace Settings Contract
 * @notice Manages configuration and settings for the SecondSwap marketplace
 * @dev Implements IMarketplaceSetting interface and handles all marketplace parameters
 */
contract SecondSwap_MarketplaceSetting is IMarketplaceSetting {    

    /**
     * @notice Fee percentage charged to buyers (in basis points)
     * @dev 100 = 1%, 10000 = 100%
     */
    uint256 public buyerFee;

    /**
     * @notice Fee percentage charged to sellers (in basis points)
     * @dev 100 = 1%, 10000 = 100%
     */
    uint256 public sellerFee;

    /**
     * @notice Fee charged for early unlisting (in wei)
     */
    uint256 public penaltyFee;

    /**
     * @notice Minimum duration a listing must remain active (in seconds)
     */
    uint256 public minListingDuration;

    /**
     * @notice Percentage of fees allocated to referrals (in basis points)
     */
    uint256 public referralFee;

    /**
     * @notice Flag indicating if marketplace is frozen
     */
    bool public isMarketplaceFreeze;

    /**
     * @notice Address that collects marketplace fees
     */
    address public feeCollector;

    /**
     * @notice Address of the marketplace admin
     */
    address public s2Admin;

    /**
     * @notice Address of the whitelist deployer contract
     */
    address public whitelistDeployer;

    /**
     * @notice Address of the vesting manager contract
     */
    address public vestingManager;

    /**
     * @notice Address that collects referral fees
     */
    address public referralFeeCollector;

    /**
     * @notice USDT address in IERC20 format
     */
    IERC20 public usdt;

    /**
     * @notice Emitted when default buyer fee is updated
     */
    event DefaultBuyerFeeUpdated(uint256 buyerFee);

    /**
     * @notice Emitted when default seller fee is updated
     */
    event DefaultSellerFeeUpdated(uint256 sellerFee);

    /**
     * @notice Emitted when penalty fee is updated
     */
    event DefaultPenaltyFeeUpdated(uint256 penaltyFee);

    /**
     * @notice Emitted when minimum listing duration is updated
     */
    event PenaltyDurationUpdated(uint256 penaltyTime);

    /**
     * @notice Emitted when marketplace freeze status is updated
     */
    event MarketplaceStatusUpdated(bool status);

    /**
     * @notice Emitted when fee collector address is updated
     */
    event FeeCollectorUpdated(address newCollector);

    /**
     * @notice Emitted when admin address is updated
     */
    event AdminUpdated(address newAdmin);

    /**
     * @notice Emitted when dev address is updated
     */
    event DevUpdated(address newDev);

    /**
     * @notice Emitted when referral percentage is updated
     */
    event ReferralUpdated(uint256 _percentage);

/**
     * @notice Initializes the marketplace settings contract
     * @dev Sets initial values for all marketplace parameters
     * @param _feeCollector Address to collect marketplace fees
     * @param _s2Admin Address of the marketplace admin
     * @param _whitelistDeployer Address of whitelist deployer contract
     * @param _vestingManager Address of vesting manager contract
     * @custom:throws SS_Marketplace_Settings: Invalid fee collector address
     * @custom:throws SS_Marketplace_Settings: Invalid admin address
     */
    constructor(
        address _feeCollector,
        address _s2Admin,
        address _whitelistDeployer,
        address _vestingManager,
        address _usdt
    ) {
        require(_feeCollector != address(0), "SS_Marketplace_Settings: Invalid fee collector address");
        require(_s2Admin != address(0), "SS_Marketplace_Settings: Invalid admin address");
        feeCollector = _feeCollector;
        s2Admin = _s2Admin;
        buyerFee = 250; // 2.5% fee
        sellerFee = 250; // 2.5% fee
        penaltyFee = 10 ether;
        minListingDuration = 120;
        referralFee = 1000;
        isMarketplaceFreeze = false;
        whitelistDeployer = _whitelistDeployer;
        vestingManager = _vestingManager;
        usdt = IERC20(_usdt);
    }

    /**
     * @notice Restricts function access to admin only
     * @dev Throws if called by any account other than the admin
     */
    modifier onlyAdmin() {
        require(msg.sender == s2Admin, "SS_Marketplace_Settings: Unauthorized user");
        _;
    }

    /**
     * @notice Sets the buyer fee percentage
     * @dev Fee is in basis points (100 = 1%)
     * @param _amount New buyer fee percentage
     * @custom:throws SS_Marketplace_Settings: Buyer fee cannot be more than 50%
     */
    function setBuyerFee(uint256 _amount) external onlyAdmin {
        require(_amount <= 5000, "SS_Marketplace_Settings: Buyer fee cannot be more than 50%");
        buyerFee = _amount;
        emit DefaultBuyerFeeUpdated(_amount);
    }

    /**
     * @notice Sets the seller fee percentage
     * @dev Fee is in basis points (100 = 1%)
     * @param _amount New seller fee percentage
     * @custom:throws SS_Marketplace_Settings: Seller fee cannot be more than 50%
     */
    function setSellerFee(uint256 _amount) external onlyAdmin {
        require(_amount <= 5000, "SS_Marketplace_Settings: Seller fee cannot be more than 50%");
        sellerFee = _amount;
        emit DefaultSellerFeeUpdated(_amount);
    }
    
    /**
     * @notice Updates the fee collector address
     * @dev The fee collector receives all marketplace fees
     * @param _address New fee collector address
     * @custom:throws SS_Marketplace_Settings: Cannot be zero address
     * @custom:throws SS_Marketplace_Settings: Cannot be the same address
     */
    function setFeeAccount(address _address) external onlyAdmin {
        require(_address != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_address != feeCollector, "SS_Marketplace_Settings: Cannot be the same address");
        feeCollector = _address;
        emit FeeCollectorUpdated(_address);
    }

    /**
     * @notice Sets the penalty fee for early unlisting
     * @dev Fee is in wei
     * @param _amount New penalty fee amount
     * @custom:throws SS_Marketplace_Settings: Penalty fee cannot be less than 0
     */
    function setPenaltyFee(uint256 _amount) external onlyAdmin {
        require(_amount > 0, "SS_Marketplace_Settings: Penalty fee cannot be less than 0");
        penaltyFee = _amount;
        emit DefaultPenaltyFeeUpdated(_amount);
    }
/**
     * @notice Sets minimum duration for listings
     * @dev Duration is in seconds
     * @param _seconds New minimum listing duration
     * @custom:throws SS_Marketplace_Settings: Duration must be greater than 0
     */
    function setMinListingDuration(uint256 _seconds) external onlyAdmin {
        require(_seconds > 0, "SS_Marketplace_Settings: Duration must be greater than 0");
        minListingDuration = _seconds;
        emit PenaltyDurationUpdated(_seconds);
    }

    /**
     * @notice Updates the admin address
     * @dev Can only be called by current admin
     * @param _user New admin address
     * @custom:throws SS_Marketplace_Settings: Unauthorized Access
     * @custom:throws SS_Marketplace_Settings: Cannot be zero address
     * @custom:throws SS_Marketplace_Settings: Cannot be the same address
     */
    function setS2Admin(address _user) external {
        require(msg.sender == s2Admin, "SS_Marketplace_Settings: Unauthorized Access");
        require(_user != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_user != s2Admin, "SS_Marketplace_Settings: Cannot be the same address");
        s2Admin = _user;
        emit AdminUpdated(_user);
    }

    /**
     * @notice Updates marketplace freeze status
     * @dev When frozen, most marketplace operations are disabled
     * @param _status New freeze status
     */
    function setMarketplaceStatus(bool _status) external onlyAdmin {
        isMarketplaceFreeze = _status;
        emit MarketplaceStatusUpdated(_status);
    }
    
    /**
     * @notice Sets the referral reward percentage
     * @dev Percentage is in basis points (100 = 1%)
     * @param _percentage New referral percentage
     * @custom:throws SS_Marketplace_Settings: Percentage value cannot be 0
     * @custom:throws SS_Marketplace_Settings: Percentage cannot be more than 100%
     */
    function setReferral(uint256 _percentage) external onlyAdmin {
        require(_percentage > 0, "SS_Marketplace_Settings: Percentage value cannot be 0");
        require(_percentage <= 10000, "SS_Marketplace_Settings: Percentage cannot be more than 100%");
        referralFee = _percentage;
        emit ReferralUpdated(_percentage);
    }
    /**
     * @notice Updates the whitelist deployer address
     * @dev The whitelist deployer creates whitelist contracts for private sales
     * @param _whitelistDeployer New whitelist deployer address
     * @custom:throws SS_Marketplace_Settings: Cannot be zero address
     * @custom:throws SS_Marketplace_Settings: Cannot be the same whitelist address
     */
    function setWhitelistDeployer(address _whitelistDeployer) external onlyAdmin {
        require(_whitelistDeployer != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_whitelistDeployer != address(whitelistDeployer), 
            "SS_Marketplace_Settings: Cannot be the same whitelist address");
        whitelistDeployer = _whitelistDeployer;
    }
    
    /**
     * @notice Updates the vesting manager address
     * @dev The vesting manager handles token vesting logic
     * @param _vestingManager New vesting manager address
     * @custom:throws SS_Marketplace_Settings: Cannot be zero address
     * @custom:throws SS_Marketplace_Settings: Cannot be the same vestingManager address
     */
    function setManager(address _vestingManager) external onlyAdmin {
        require(_vestingManager != address(0), "SS_Marketplace_Settings: Cannot be zero address");
        require(_vestingManager != address(vestingManager), 
            "SS_Marketplace_Settings: Cannot be the same vestingManager address");
        vestingManager = _vestingManager;
    }

    /**
     * @notice Retrieves buyer and seller fees for a specific vesting plan
     * @dev Returns -1 if no specific fees are set for the plan
     * @param _vesting Address of the vesting plan
     * @return VPbuyerFee Buyer fee for the vesting plan
     * @return VPsellerFee Seller fee for the vesting plan
     */
    function getVestingFees(address _vesting) public view returns (int256 VPbuyerFee, int256 VPsellerFee) {
        (VPbuyerFee, VPsellerFee) = IVestingManager(vestingManager).getVestingFees(_vesting);
        return (VPbuyerFee, VPsellerFee);
    }
}

contracts/SecondSwap_StepVesting.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interface/SecondSwap_Vesting.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol"; //  3.6. DOS caused by the use of transfer and transferFrom functions

/**
 * @title SecondSwap Step Vesting Contract
 * @notice Manages token vesting with linear steps over time
 * @dev Implements SecondSwap_Vesting interface for step-based token vesting
 */
contract SecondSwap_StepVesting is SecondSwap_Vesting {
    using SafeERC20 for IERC20;

    /**
     * @notice Emitted when a new vesting schedule is created
     * @param beneficiary Address receiving the vested tokens
     * @param totalAmount Total amount of tokens being vested
     */
    event VestingCreated(address indexed beneficiary, uint256 totalAmount);

    /**
     * @notice Emitted when vesting is transferred between addresses
     * @param grantor Address transferring the vesting
     * @param beneficiary Address receiving the vesting
     * @param amount Amount of tokens transferred
     */
    event VestingTransferred(address indexed grantor, address indexed beneficiary, uint256 amount);

    /**
     * @notice Emitted when tokens are claimed from vesting
     * @param beneficiary Address claiming the tokens
     * @param amount Amount of tokens claimed
     */
    event Claimed(address indexed beneficiary, uint256 amount);

    /**
     * @notice The ERC20 token being vested
     */
    IERC20 public immutable token;

    /**
     * @notice Structure containing vesting details for each beneficiary
     * @param stepsClaimed Number of vesting steps already claimed
     * @param amountClaimed Total amount of tokens claimed so far
     * @param releaseRate Number of tokens released per step
     * @param totalAmount Total amount of tokens in the vesting schedule
     */
    struct Vesting {
        uint256 stepsClaimed;
        uint256 amountClaimed;
        uint256 releaseRate;
        uint256 totalAmount;
    }

    /**
     * @notice Start time of the vesting schedule
     */
    uint256 immutable public startTime;

    /**
     * @notice End time of the vesting schedule
     */
    uint256 immutable public endTime;

    /**
     * @notice Total number of vesting steps
     */
    uint256 immutable public numOfSteps;

    /**
     * @notice Duration of each vesting step
     */
    uint256 immutable public stepDuration;

    /**
     * @notice Mapping of beneficiary addresses to their vesting details
     */
    mapping (address => Vesting) public _vestings;

    /**
     * @notice Address of the vesting deployer contract
     */
    address public vestingDeployer;

    /**
     * @notice Address of the manager contract
     */
    address public manager;

    /**
     * @notice Address of the token issuer
     */
    address public tokenIssuer;

	/**
     * @notice Restricts function access to manager only
     * @dev Throws if called by any account other than the manager
     */
    modifier onlyManager() {
        require(msg.sender == manager, "SS_StepVesting: caller is not the manager");
        _;
    }

    /**
     * @notice Initializes the vesting contract
     * @param _tokenIssuer Address authorized to issue tokens
     * @param _manager Address of the manager contract
     * @param _token Address of the ERC20 token
     * @param _startTime Start time of vesting schedule
     * @param _endTime End time of vesting schedule
     * @param _numOfSteps Number of vesting steps
     * @param _vestingDeployer Address of vesting deployer contract
     */
    constructor(
        address _tokenIssuer,
        address _manager,
        IERC20 _token,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _numOfSteps,
        address _vestingDeployer
    ) {
        vestingDeployer = _vestingDeployer;
        tokenIssuer = _tokenIssuer;
        manager = _manager;
        token = _token;
        startTime = _startTime;
        endTime = _endTime;
        numOfSteps = _numOfSteps;
        stepDuration = (_endTime - _startTime) / _numOfSteps;
    }

    /**
     * @notice Returns available (unclaimed) tokens for a beneficiary
     * @param _beneficiary Address to check
     * @return Amount of tokens available to claim
     */
    function available(address _beneficiary) external view returns (uint256) {
        return _vestings[_beneficiary].totalAmount - _vestings[_beneficiary].amountClaimed;
    }

    /**
     * @notice Returns total vesting amount for a beneficiary
     * @param _beneficiary Address to check
     * @return Total amount of tokens in vesting schedule
     */
    function total(address _beneficiary) external view returns (uint256) {
        return _vestings[_beneficiary].totalAmount;
    }

    /**
     * @notice Calculates claimable tokens for a beneficiary
     * @dev Returns both claimable amount and number of steps that can be claimed
     * @param _beneficiary Address to calculate for
     * @return Amount of tokens claimable
     * @return Number of steps claimable
     */
    function claimable(address _beneficiary) public view returns (uint256, uint256) {
        Vesting memory vesting = _vestings[_beneficiary];
        if (vesting.totalAmount == 0) {
            return (0, 0);
        }

        uint256 currentTime = Math.min(block.timestamp, endTime);
        if (currentTime < startTime) {
            return (0, 0);
        }

        uint256 elapsedTime = currentTime - startTime;
        uint256 currentStep = elapsedTime / stepDuration;
        uint256 claimableSteps = currentStep - vesting.stepsClaimed;
        
        uint256 claimableAmount;

        if (vesting.stepsClaimed + claimableSteps >= numOfSteps) { //[BUG FIX] user can buy more than they are allocated
            claimableAmount = vesting.totalAmount - vesting.amountClaimed;
            return (claimableAmount, claimableSteps);
        }

        claimableAmount = vesting.releaseRate * claimableSteps;
        return (claimableAmount, claimableSteps);
    }

    /**
     * @notice Claims available tokens
     * @dev Transfers claimable tokens to msg.sender
     * @custom:throws SS_StepVesting: nothing to claim
     */
    function claim() external {
        (uint256 claimableAmount, uint256 claimableSteps) = claimable(msg.sender);
        require(claimableAmount > 0, "SS_StepVesting: nothing to claim");

        Vesting storage vesting = _vestings[msg.sender];
        vesting.stepsClaimed += claimableSteps;
        vesting.amountClaimed += claimableAmount;

        token.safeTransfer(msg.sender, claimableAmount); //  3.6. DOS caused by the use of transfer and transferFrom functions
        emit Claimed(msg.sender, claimableAmount);
    }
	
	/**
     * @notice Transfers vesting from one address to another
     * @dev Can only be called by authorized addresses
     * @param _grantor Address transferring the vesting
     * @param _beneficiary Address receiving the vesting
     * @param _amount Amount of tokens to transfer
     * @custom:throws SS_StepVesting: unauthorized
     * @custom:throws SS_StepVesting: beneficiary is zero
     * @custom:throws SS_StepVesting: amount is zero
     * @custom:throws SS_StepVesting: insufficient balance
     */
    function transferVesting(
        address _grantor,
        address _beneficiary,
        uint256 _amount
    ) external {
        require(msg.sender == tokenIssuer || msg.sender == manager || msg.sender == vestingDeployer, "SS_StepVesting: unauthorized");
        require(_beneficiary != address(0), "SS_StepVesting: beneficiary is zero");
        require(_amount > 0, "SS_StepVesting: amount is zero");
        Vesting storage grantorVesting = _vestings[_grantor];
		require(grantorVesting.totalAmount - grantorVesting.amountClaimed >= _amount , "SS_StepVesting: insufficient balance"); // 3.8. Claimed amount not checked in transferVesting function

        grantorVesting.totalAmount -= _amount;
        grantorVesting.releaseRate = grantorVesting.totalAmount / numOfSteps;

        _createVesting(_beneficiary, _amount, grantorVesting.stepsClaimed, true);

        emit VestingTransferred(_grantor, _beneficiary, _amount);
    }

    /**
     * @notice Creates a new vesting schedule for a beneficiary
     * @dev Can only be called by authorized addresses
     * @param _beneficiary Address to receive the vesting
     * @param _totalAmount Total amount of tokens to vest
     * @custom:throws SS_StepVesting: unauthorized
     */
    function createVesting(
        address _beneficiary,
        uint256 _totalAmount
    ) external {
        require(msg.sender == tokenIssuer || msg.sender == manager || msg.sender == vestingDeployer, "SS_StepVesting: unauthorized");
        _createVesting(_beneficiary, _totalAmount, 0, false);
    }

    /**
     * @notice Creates multiple vesting schedules in batch
     * @dev Can only be called by authorized addresses
     * @param _beneficiaries Array of addresses to receive vesting
     * @param _totalAmounts Array of token amounts to vest
     * @custom:throws SS_StepVesting: unauthorized
     * @custom:throws SS_StepVesting: array length mismatch
     */
    function createVestings(
        address[] memory _beneficiaries,
        uint256[] memory _totalAmounts
    ) external {
        require(msg.sender == tokenIssuer || msg.sender == manager || msg.sender == vestingDeployer, "unauthorized");
        require(_beneficiaries.length == _totalAmounts.length, "SS_StepVesting: array length mismatch");

        for (uint256 i = 0; i < _beneficiaries.length; i++) {
            _createVesting(_beneficiaries[i], _totalAmounts[i], 0, false);
        }
    }

    /**
     * @notice Internal function to create vesting schedule
     * @dev Handles both new vestings and additions to existing vestings
     * @param _beneficiary Address to receive vesting
     * @param _totalAmount Amount of tokens to vest
     * @param _stepsClaimed Number of steps already claimed (for transfers)
     * @param _isInternal Whether this is an internal transfer
     * @custom:throws SS_StepVesting: beneficiary is zero
     * @custom:throws SS_StepVesting: total amount is zero
     */
    function _createVesting(
        address _beneficiary,
        uint256 _totalAmount,
        uint256 _stepsClaimed,
        bool _isInternal
    ) internal {
        require(_beneficiary != address(0), "SS_StepVesting: beneficiary is zero");
        require(_totalAmount > 0, "SS_StepVesting: total amount is zero");

        if (_vestings[_beneficiary].totalAmount == 0) {
            _vestings[_beneficiary] = Vesting({
                stepsClaimed: _stepsClaimed,
                amountClaimed: 0,
                releaseRate: _totalAmount / (numOfSteps - _stepsClaimed),
                totalAmount: _totalAmount
            });
        } else {
            _vestings[_beneficiary].totalAmount += _totalAmount;
            if(numOfSteps - _vestings[_beneficiary].stepsClaimed != 0) {
                _vestings[_beneficiary].releaseRate = (_vestings[_beneficiary].totalAmount - _vestings[_beneficiary].amountClaimed) 
                    / (numOfSteps - _vestings[_beneficiary].stepsClaimed);
            } else {
                _vestings[_beneficiary].releaseRate = 0;
            }
        }
        
        if (!_isInternal) {
            token.transferFrom(tokenIssuer, address(this), _totalAmount);
        }
        emit VestingCreated(_beneficiary, _totalAmount);
    }
}

contracts/SecondSwap_VestingDeployer.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./SecondSwap_StepVesting.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title SecondSwap Vesting Deployer Contract
 * @notice Manages the deployment and configuration of vesting contracts
 * @dev Upgradeable contract that handles vesting contract deployment and management
 */
contract SecondSwap_VestingDeployer is Initializable {
    
    /**
     * @notice Emitted when a new vesting contract is deployed
     * @param token Address of the token being vested
     * @param vesting Address of the deployed vesting contract
     * @param vestingId Unique identifier for the vesting contract
     */
    event VestingDeployed(address indexed token, address vesting, string vestingId);

    /**
     * @notice Emitted when a new vesting schedule is created
     * @param beneficiary Address receiving the vested tokens
     * @param totalAmount Amount of tokens being vested
     * @param stepVesting Address of the step vesting contract
     */
    event VestingCreated(address indexed beneficiary, uint256 totalAmount, address stepVesting);

    /**
     * @notice Emitted when vesting is transferred between addresses
     * @param grantor Address transferring the vesting
     * @param beneficiary Address receiving the vesting
     * @param amount Amount of tokens transferred
     * @param stepVesting Address of the step vesting contract
     * @param transactionId Unique identifier for the transfer
     */
    event VestingTransferred(
        address indexed grantor,
        address indexed beneficiary,
        uint256 amount,
        address stepVesting,
        string transactionId
    );

    /**
     * @notice Emitted when tokens are claimed from vesting
     * @param beneficiary Address claiming the tokens
     * @param stepVesting Address of the step vesting contract
     * @param amount Amount of tokens claimed
     */
    event VestingClaimed(address indexed beneficiary, address stepVesting, uint256 amount);

    /**
     * @notice Address of the vesting manager contract
     */
    address public manager;

    /**
     * @notice Mapping of addresses to their owned tokens
     * @dev Maps token owner address to token address
     */
    mapping(address => address) public _tokenOwner;

    /**
     * @notice Address of the admin
     */
    address public s2Admin;

    /**
     * @notice Initializes the vesting deployer contract
     * @dev Implementation of initializer for upgradeable pattern
     * @param _s2Admin Address of the admin
     * @param _manager Address of the manager contract
     */
    function initialize(address _s2Admin, address _manager) public initializer {
        s2Admin = _s2Admin;
        manager = _manager;
    }

    /**
     * @notice Restricts function access to admin only
     * @custom:throws SS_VestingDeployer: Unauthorized user
     */
    modifier onlyAdmin() {
        require(msg.sender == s2Admin, "SS_VestingDeployer: Unauthorized user");
        _;
    }

    /**
     * @notice Deploys a new vesting contract
     * @dev Creates a new StepVesting contract instance and makes it sellable
     * @param tokenAddress Address of the token to be vested
     * @param startTime Start time of the vesting schedule
     * @param endTime End time of the vesting schedule
     * @param steps Number of vesting steps
     * @param vestingId Unique identifier for the vesting contract
     * @custom:throws SS_VestingDeployer: caller is not the token owner
     * @custom:throws SS_VestingDeployer: start time must be before end time
     * @custom:throws SS_VestingDeployer: steps must be greater than 0
     * @custom:throws SS_VestingDeployer: manager not set
     */
    function deployVesting(
        address tokenAddress,
        uint256 startTime,
        uint256 endTime,
        uint256 steps,
        string memory vestingId
    ) external {
        require(_tokenOwner[msg.sender] == tokenAddress, "SS_VestingDeployer: caller is not the token owner");
        //require(_tokenOwner[msg.sender] == address(SecondSwap_StepVesting(_stepVesting).token()), "SS_VestingDeployer: caller is not the token owner"); Can't implement this as the stepVesting Contract is not deployed
        require(tokenAddress != address(0), "SS_VestingDeployer: token address is zero");// 3.2. Arbitrary transfer of vesting

        require(startTime < endTime, "SS_VestingDeployer: start time must be before end time");
        require(steps > 0, "SS_VestingDeployer: steps must be greater than 0");
        require(manager != address(0), "SS_VestingDeployer: manager not set");

        address newVesting = address(new SecondSwap_StepVesting(
            msg.sender,
            manager,
            IERC20(tokenAddress),
            startTime,
            endTime,
            steps,
            address(this)
        ));
        IVestingManager(manager).setSellable(newVesting, true);
        emit VestingDeployed(tokenAddress, newVesting, vestingId);
    }

    /**
     * @notice Sets the owner for a token
     * @dev Maps token address to owner address
     * @param token Address of the token
     * @param _owner Address to be set as owner
     * @custom:throws Existing token have owner
     */
    function setTokenOwner(address token, address _owner) external onlyAdmin {
        require(_tokenOwner[_owner] == address(0), "SS_VestingDeployer: Existing token have owner");
        _tokenOwner[_owner] = token;
    }

    /**
     * @notice Updates the manager address
     * @dev Sets new manager address for vesting management
     * @param _manager New manager address
     * @custom:throws Cannot assign the same address
     */
    function setManager(address _manager) external onlyAdmin {
        require(manager != _manager, "SS_VestingDeployer: Cannot assign the same address");
        manager = _manager;
    }

    /**
     * @notice Updates the admin address
     * @dev Sets new admin address for vesting management
     * @param _admin New admin address
     * @custom:throws Cannot assign the same address
     */
    function setAdmin(address _admin) external onlyAdmin {
      require(s2Admin != _admin,"SS_VestingDeployer: Cannot assign the same address");
      s2Admin = _admin;
    }
    
    /**
     * @notice Creates a new vesting schedule
     * @dev Creates vesting for a single beneficiary
     * @param tokenAddress Address of the token to vest
     * @param _beneficiary Address receiving the vesting
     * @param _totalAmount Amount of tokens to vest
     * @param _stepVesting Address of the step vesting contract
     * @custom:throws SS_VestingDeployer: caller is not the token owner
     */
    function createVesting(
        address tokenAddress,
        address _beneficiary,
        uint256 _totalAmount,
        address _stepVesting
    ) external {
        require(tokenAddress != address(0), "SS_VestingDeployer: token address is zero");// 3.2. Arbitrary transfer of vesting
        require(_tokenOwner[msg.sender] == address(SecondSwap_StepVesting(_stepVesting).token()), "SS_VestingDeployer: caller is not the token owner");// 3.2. Arbitrary transfer of vesting
        SecondSwap_StepVesting(_stepVesting).createVesting(_beneficiary, _totalAmount);
        emit VestingCreated(_beneficiary, _totalAmount, _stepVesting);
    }

    /**
     * @notice Creates multiple vesting schedules in batch
     * @dev Creates vestings for multiple beneficiaries
     * @param tokenAddress Address of the token to vest
     * @param _beneficiaries Array of beneficiary addresses
     * @param _totalAmounts Array of vesting amounts
     * @param _stepVesting Address of the step vesting contract
     * @custom:throws SS_VestingDeployer: caller is not the token owner
     */
    function createVestings(
        address tokenAddress,
        address[] memory _beneficiaries,
        uint256[] memory _totalAmounts,
        address _stepVesting
    ) external {
        require(tokenAddress != address(0), "SS_VestingDeployer: token address is zero");// 3.2. Arbitrary transfer of vesting
        require(_tokenOwner[msg.sender] == address(SecondSwap_StepVesting(_stepVesting).token()), "SS_VestingDeployer: caller is not the token owner");// 3.2. Arbitrary transfer of vesting
        SecondSwap_StepVesting(_stepVesting).createVestings(_beneficiaries, _totalAmounts);
        for (uint256 i = 0; i < _beneficiaries.length; i++) {
            emit VestingCreated(_beneficiaries[i], _totalAmounts[i], _stepVesting);
        }
    }

    /**
     * @notice Transfers vesting between addresses
     * @dev Transfers vesting tokens from grantor to beneficiary
     * @param tokenAddress Address of the token being transferred
     * @param _grantor Address transferring the vesting
     * @param _beneficiary Address receiving the vesting
     * @param _amount Amount of tokens to transfer
     * @param _stepVesting Address of the step vesting contract
     * @param _transactionId Unique identifier for the transfer
     * @custom:throws SS_VestingDeployer: caller is not the token owner
     */
    function transferVesting(
        address tokenAddress,
        address _grantor,
        address _beneficiary,
        uint256 _amount,
        address _stepVesting,
        string memory _transactionId
    ) external {
        require(tokenAddress != address(0), "SS_VestingDeployer: token address is zero"); // 3.2. Arbitrary transfer of vesting
        require(_tokenOwner[msg.sender] == address(SecondSwap_StepVesting(_stepVesting).token()), "SS_VestingDeployer: caller is not the token owner"); // 3.2. Arbitrary transfer of vesting
        SecondSwap_StepVesting(_stepVesting).transferVesting(_grantor, _beneficiary, _amount);
        emit VestingTransferred(_grantor, _beneficiary, _amount, _stepVesting, _transactionId);
    }

    /**
     * @notice Returns the current version of the contract
     * @return String representing the contract version
     */
    function version() public pure returns (string memory) {
        return "1.0.0";
    }
}

contracts/SecondSwap_VestingManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "./interface/SecondSwap_Vesting.sol";
import "./SecondSwap_StepVesting.sol";
import "./interface/SecondSwap_IVestingManager.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SecondSwap Vesting Manager Contract
 * @notice Manages vesting settings, allocations, and marketplace interactions
 * @dev Implements IVestingManager interface to handle vesting operations
 */
contract SecondSwap_VestingManager is IVestingManager {

    /**
     * @notice Tracks bought and sold amounts for each user's vesting allocation
     * @param bought Amount of tokens bought by the user
     * @param sold Amount of tokens sold by the user
     */
    struct Allocation {
        uint256 bought;
        uint256 sold;
    }

    /**
     * @notice Emitted when a vesting plan's sellable status is updated
     * @param vesting Address of the vesting contract
     * @param sellable New sellable status
     */
    event VestingSellableUpdated(address vesting, bool sellable);

    /**
     * @notice Emitted when maximum sell percentage is updated
     * @param vesting Address of the vesting contract
     * @param maxSellPercent New maximum sell percentage
     */
    event MaxSellPercentUpdated(address vesting, uint256 maxSellPercent);

    /**
     * @notice Emitted when buyer fee is updated
     * @param vesting Address of the vesting contract
     * @param fee New buyer fee
     */
    event BuyerFeeUpdated(address vesting, int256 fee);

    /**
     * @notice Emitted when seller fee is updated
     * @param vesting Address of the vesting contract
     * @param fee New seller fee
     */
    event SellerFeeUpdated(address vesting, int256 fee);

    /**
     * @notice Maps vesting contract addresses to their settings
     */
    mapping(address => VestingSettings) public vestingSettings;

    /**
     * @notice Maps user addresses to their vesting allocations
     * @dev First key is user address, second key is vesting plan address
     */
    mapping(address => mapping(address => Allocation)) public allocations;

    /**
     * @notice Address of the marketplace contract
     */
    address public marketplace;

    /**
     * @notice Address of the admin
     */
    address public s2Admin;

    /**
     * @notice Address of the vesting deployer
     */
    address public vestingDeployer;

    /**
     * @notice Base unit for percentage calculations (100% = 10000)
     */
    uint256 BASE = 10000;

    /**
     * @notice Restricts function access to marketplace only
     */
    modifier onlyMarketplace() {
        require(msg.sender == marketplace, "SS_VestingManager: caller is not marketplace");
        _;
    }

    /**
     * @notice Restricts function access to admin only
     */
    modifier onlyAdmin() {
        require(msg.sender == s2Admin, "SS_VestingManager: Unauthorized user");
        _;
    }

    /**
     * @notice Initializes the vesting manager
     * @param _s2admin Address of the admin
     */
    constructor(address _s2admin) {
        s2Admin = _s2admin;
    }

    /**
     * @notice Lists tokens for sale in the marketplace
     * @dev Validates selling limits and transfers tokens to contract
     * @param seller Address of the token seller
     * @param plan Address of the vesting plan
     * @param amount Amount of tokens to list
     * @custom:throws vesting not sellable
     * @custom:throws SS_VestingManager: insufficient availablility
     * @custom:throws SS_VestingManager: cannot list more than max sell percent
     */
    function listVesting(address seller, address plan, uint256 amount) external onlyMarketplace {
        require(vestingSettings[plan].sellable, "vesting not sellable");
        require(SecondSwap_Vesting(plan).available(seller) >= amount, "SS_VestingManager: insufficient availablility");

        Allocation storage userAllocation = allocations[seller][plan];

        uint256 sellLimit = userAllocation.bought;
        uint256 currentAlloc = SecondSwap_Vesting(plan).total(seller);
        if (currentAlloc + userAllocation.sold > userAllocation.bought) {
            sellLimit += (currentAlloc + userAllocation.sold - userAllocation.bought) * vestingSettings[plan].maxSellPercent / BASE;
        }

        userAllocation.sold += amount;

        require(userAllocation.sold <= sellLimit, "SS_VestingManager: cannot list more than max sell percent");
        SecondSwap_Vesting(plan).transferVesting(seller, address(this), amount);
    }

    /**
     * @notice Removes tokens from marketplace listing
     * @dev Returns tokens to seller
     * @param seller Address of the token seller
     * @param plan Address of the vesting plan
     * @param amount Amount of tokens to unlist
     */
    function unlistVesting(address seller, address plan, uint256 amount) external onlyMarketplace {
        allocations[seller][plan].sold -= amount;
        SecondSwap_Vesting(plan).transferVesting(address(this), seller, amount);
    }

    /**
     * @notice Completes a purchase of vested tokens
     * @dev Updates buyer allocation and transfers tokens
     * @param buyer Address of the token buyer
     * @param vesting Address of the vesting contract
     * @param amount Amount of tokens purchased
     */
    function completePurchase(address buyer, address vesting, uint256 amount) external onlyMarketplace {
        allocations[buyer][vesting].bought += amount;
        SecondSwap_Vesting(vesting).transferVesting(address(this), buyer, amount);
    }

    /**
     * @notice Sets whether tokens can be sold from a vesting contract
     * @dev Also initializes default settings for new sellable vestings
     * @param vesting Address of the vesting contract
     * @param sellable Whether the tokens can be sold
     * @custom:throws SS_VestingManager: Unauthorised user
     */
    function setSellable(address vesting, bool sellable) external {
        require(s2Admin == msg.sender || vestingDeployer == msg.sender, "SS_VestingManager: Unauthorised user");    

        VestingSettings storage vestingSetting = vestingSettings[vesting];

        vestingSetting.sellable = sellable;
        if (vestingSetting.maxSellPercent == 0 && vestingSetting.sellable) {
            vestingSetting.maxSellPercent = 2000;
            vestingSetting.buyerFee = -1;
            vestingSetting.sellerFee = -1;
            emit MaxSellPercentUpdated(vesting, 2000);
        }
        emit VestingSellableUpdated(vesting, sellable);
    }

    /**
     * @notice Sets maximum percentage of tokens that can be sold
     * @param vesting Address of the vesting contract
     * @param maxSellPercent Maximum percentage allowed to sell
     * @custom:throws SS_VestingManager: Invalid Token Issuer
     */
    function setMaxSellPercent(address vesting, uint256 maxSellPercent) external {
        require(SecondSwap_StepVesting(vesting).tokenIssuer() == msg.sender, "SS_VestingManager: Invalid Token Issuer");
        vestingSettings[vesting].maxSellPercent = maxSellPercent;
        emit MaxSellPercentUpdated(vesting, maxSellPercent);
    }

    /**
     * @notice Sets the marketplace address
     * @param _marketplace New marketplace address
     */
    function setMarketplace(address _marketplace) external onlyAdmin {
        marketplace = _marketplace;
    }

    /**
     * @notice Updates the admin address
     * @param _admin New admin address
     */
    function setAdmin(address _admin) external onlyAdmin {
        s2Admin = _admin;
    }

    /**
     * @notice Sets buyer fee for a vesting contract
     * @dev Fee can be -1 for default fee
     * @param _vesting Address of the vesting contract
     * @param _fee New buyer fee (-1 to 5000)
     * @custom:throws SS_VestingManager: Buyer Fee cannot be less than 0
     */
    function setBuyerFee(address _vesting, int256 _fee) external onlyAdmin {
        require(_fee >= -1 && _fee <= 5000, "SS_VestingManager: Buyer Fee cannot be less than 0");
        vestingSettings[_vesting].buyerFee = _fee;
        emit BuyerFeeUpdated(_vesting, _fee);
    }

    /**
     * @notice Sets seller fee for a vesting contract
     * @dev Fee can be -1 for default fee
     * @param _vesting Address of the vesting contract
     * @param _fee New seller fee (-1 to 5000)
     * @custom:throws SS_VestingManager: Seller fee cannot be less than 0
     */
    function setSellerFee(address _vesting, int256 _fee) external onlyAdmin {
        require(_fee >= -1 && _fee <= 5000, "SS_VestingManager: Seller fee cannot be less than 0");
        vestingSettings[_vesting].sellerFee = _fee;
        emit SellerFeeUpdated(_vesting, _fee);
    }

    /**
     * @notice Updates the vesting deployer address
     * @param _vestingDeployer New vesting deployer address
     * @custom:throws SS_VestingManager: VestingDeployer cannot be the same
     */
    function setVestingDeployer(address _vestingDeployer) external onlyAdmin {
        require(_vestingDeployer != vestingDeployer, "SS_VestingManager: VestingDeployer cannot be the same");
        vestingDeployer = _vestingDeployer;
    }

    /**
     * @notice Gets buyer and seller fees for a vesting plan
     * @param _vestingPlan Address of the vesting plan
     * @return buyerFee Current buyer fee
     * @return sellerFee Current seller fee
     */
    function getVestingFees(address _vestingPlan) external view returns (int256 buyerFee, int256 sellerFee) {
        return (vestingSettings[_vestingPlan].buyerFee, vestingSettings[_vestingPlan].sellerFee);
    }
}

